'use client';

import { useState } from 'react';
import { POI_HIYERARSI, POI_ALT_ETIKETLER, POI_GENEL_ETIKETLER } from '../../lib/poi-constants';

interface Props {
  userLat: number | null;
  userLng: number | null;
  onKapat: () => void;
  onBasarili: () => void;
}

export default function PoiEkleModal({ onKapat, onBasarili }: Props) {
  const [form, setForm] = useState({
    name: '',
    description: '',
    categories: [] as string[],  // seçili alt kategori değerleri (çoklu)
    latitude: '',
    longitude: '',
    address: '',
    city: '',
    district: '',
    address_note: '',
    phone: '',
    is_emergency: false,
  });
  const [aktifAnaKat, setAktifAnaKat] = useState('');
  const [secilenEtiketler, setSecilenEtiketler] = useState<string[]>([]);
  const [gonderiliyor, setGonderiliyor] = useState(false);
  const [hata, setHata] = useState('');
  const [adimlar] = useState(0);
  const [konumDurum, setKonumDurum] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const [konumHata, setKonumHata] = useState('');

  const konumAl = () => {
    if (!navigator.geolocation) {
      setKonumDurum('error');
      setKonumHata('Tarayıcınız konum özelliğini desteklemiyor.');
      return;
    }
    setKonumDurum('loading');
    setKonumHata('');
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setForm(prev => ({
          ...prev,
          latitude: pos.coords.latitude.toFixed(6),
          longitude: pos.coords.longitude.toFixed(6),
        }));
        setKonumDurum('success');
      },
      (err) => {
        setKonumDurum('error');
        if (err.code === err.PERMISSION_DENIED) {
          setKonumHata('Konum izni reddedildi. Tarayıcı ayarlarından konum iznini verin.');
        } else if (err.code === err.POSITION_UNAVAILABLE) {
          setKonumHata('Konum alınamadı. GPS sinyali yok veya cihaz desteklemiyor.');
        } else {
          setKonumHata('Konum alımı zaman aşımına uğradı. Tekrar deneyin.');
        }
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const toggleEtiket = (e: string) => {
    setSecilenEtiketler(prev =>
      prev.includes(e) ? prev.filter(x => x !== e) : [...prev, e]
    );
  };

  const handleGonder = async () => {
    if (!form.name || form.categories.length === 0 || !form.latitude || !form.longitude) {
      setHata('İsim, kategori ve koordinat zorunludur.');
      return;
    }
    setGonderiliyor(true);
    setHata('');
    try {
      const res = await fetch('/api/poi', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...form,
          category: form.categories[0],      // birincil kategori (backward compat)
          latitude: parseFloat(form.latitude),
          longitude: parseFloat(form.longitude),
          tags: secilenEtiketler,
        }),
      });
      const json = await res.json();
      if (json.success) {
        onBasarili();
      } else if (res.status === 409 && json.duplicate) {
        setHata(`⚠️ ${json.error}`);
      } else {
        setHata(json.error || 'Bir hata oluştu.');
      }
    } catch {
      setHata('Bağlantı hatası.');
    } finally {
      setGonderiliyor(false);
    }
  };

  return (
    <div
      onClick={onKapat}
      style={{
        position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)',
        zIndex: 1100, display: 'flex', alignItems: 'flex-end',
      }}
    >
      <div
        onClick={e => e.stopPropagation()}
        style={{
          width: '100%', maxHeight: '92dvh',
          background: '#161b22', borderRadius: '16px 16px 0 0',
          overflowY: 'auto', padding: '0 0 40px',
        }}
      >
        <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
        {/* Başlık */}
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          padding: '16px 20px 12px', borderBottom: '1px solid #21262d',
          position: 'sticky', top: 0, background: '#161b22', zIndex: 10,
        }}>
          <div style={{ fontWeight: 700, fontSize: 16, color: '#e6edf3' }}>
            Yeni Yer Ekle
          </div>
          <button
            onClick={onKapat}
            style={{ background: 'none', border: 'none', color: '#8b949e', fontSize: 20, cursor: 'pointer' }}
          >
            ✕
          </button>
        </div>

        <div style={{ padding: '16px 20px' }}>
          {adimlar === 0 && (
            <div style={{
              background: '#0d1117', borderRadius: 8, padding: 12, marginBottom: 16,
              fontSize: 13, color: '#8b949e', lineHeight: 1.5,
            }}>
              ℹ️ Eklediğiniz konum incelendikten sonra haritada yayınlanacaktır. Teşekkürler!
            </div>
          )}

          {/* İsim */}
          <label style={labelStyle}>İşletme / Konum Adı *</label>
          <input
            value={form.name}
            onChange={e => setForm({ ...form, name: e.target.value })}
            placeholder="Örn: Güven Tır Parkı"
            style={inputStyle}
          />

          {/* Kategori — 2 kademeli */}
          <label style={labelStyle}>Kategori *</label>

          {/* 1. Adım: Ana kategori */}
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 7, marginBottom: 10 }}>
            {POI_HIYERARSI.map(ana => {
              const secili = aktifAnaKat === ana.value;
              return (
                <button
                  key={ana.value}
                  type="button"
                  onClick={() => { setAktifAnaKat(ana.value); setForm({ ...form, categories: [] }); }}
                  style={{
                    padding: '7px 12px', borderRadius: 8, fontSize: 13,
                    border: `1px solid ${secili ? ana.pinColor : '#30363d'}`,
                    background: secili ? ana.pinColor + '22' : 'transparent',
                    color: secili ? ana.pinColor : '#8b949e',
                    cursor: 'pointer', fontWeight: secili ? 600 : 400,
                    display: 'flex', alignItems: 'center', gap: 5,
                  }}
                >
                  <span>{ana.icon}</span><span>{ana.label}</span>
                </button>
              );
            })}
          </div>

          {/* 2. Adım: Alt kategori */}
          {aktifAnaKat && (
            <>
              <div style={{ fontSize: 11, color: '#4b5563', marginBottom: 6, paddingLeft: 2 }}>
                Alt kategori seçin:
              </div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 16 }}>
                {POI_HIYERARSI.find(a => a.value === aktifAnaKat)?.altlar.map(alt => {
                  const secili = form.categories.includes(alt.value);
                  return (
                    <button
                      key={alt.value}
                      type="button"
                      onClick={() => {
                        const cats = secili
                          ? form.categories.filter(c => c !== alt.value)
                          : [...form.categories, alt.value];
                        setForm({ ...form, categories: cats });
                      }}
                      style={{
                        padding: '6px 11px', borderRadius: 8, fontSize: 12,
                        border: `1px solid ${secili ? '#22c55e' : '#30363d'}`,
                        background: secili ? '#14532d' : 'transparent',
                        color: secili ? '#22c55e' : '#8b949e',
                        cursor: 'pointer', fontWeight: secili ? 600 : 400,
                        display: 'flex', alignItems: 'center', gap: 4,
                      }}
                    >
                      <span>{alt.icon}</span><span>{alt.label}</span>
                    </button>
                  );
                })}
              </div>
            </>
          )}

          {/* Özellikler / Etiketler */}
          {(() => {
            const etiketler = form.categories.length > 0
              ? [...new Set(form.categories.flatMap(k => POI_ALT_ETIKETLER[k] ?? []))]
              : POI_GENEL_ETIKETLER;
            if (etiketler.length === 0) return null;
            return (
              <>
                <label style={labelStyle}>Özellikler / Etiketler</label>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 16 }}>
                  {etiketler.map(e => (
                    <button
                      key={e}
                      type="button"
                      onClick={() => toggleEtiket(e)}
                      style={{
                        padding: '5px 10px', borderRadius: 16, fontSize: 12,
                        border: `1px solid ${secilenEtiketler.includes(e) ? '#22c55e' : '#30363d'}`,
                        background: secilenEtiketler.includes(e) ? '#14532d' : 'transparent',
                        color: secilenEtiketler.includes(e) ? '#22c55e' : '#8b949e',
                        cursor: 'pointer',
                      }}
                    >
                      {e}
                    </button>
                  ))}
                </div>
              </>
            );
          })()}

          {/* Koordinat — GPS butonu */}
          <label style={labelStyle}>Konum *</label>
          <button
            type="button"
            onClick={konumDurum === 'loading' ? undefined : konumAl}
            style={{
              width: '100%', padding: '12px 16px', borderRadius: 8,
              border: `1px solid ${konumDurum === 'success' ? '#22c55e' : konumDurum === 'error' ? '#ef4444' : '#30363d'}`,
              background: konumDurum === 'success' ? '#0d2b1a' : konumDurum === 'loading' ? '#1a2535' : '#0d1117',
              color: konumDurum === 'success' ? '#22c55e' : konumDurum === 'error' ? '#f87171' : '#e6edf3',
              fontSize: 14, fontWeight: 600, cursor: konumDurum === 'loading' ? 'wait' : 'pointer',
              marginBottom: konumDurum === 'success' ? 6 : 14,
              textAlign: 'left', display: 'flex', alignItems: 'center', gap: 8,
              fontFamily: "'IBM Plex Sans', sans-serif",
            }}
          >
            {konumDurum === 'loading' && (
              <span style={{ display: 'inline-block', width: 14, height: 14, border: '2px solid #60a5fa', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 0.7s linear infinite', flexShrink: 0 }} />
            )}
            {konumDurum === 'idle'    && '📍 Konumumu Al'}
            {konumDurum === 'loading' && 'Konum alınıyor...'}
            {konumDurum === 'success' && '✅ Konum Alındı'}
            {konumDurum === 'error'   && '📍 Tekrar Dene'}
          </button>
          {konumDurum === 'success' && (
            <div style={{ fontSize: 12, color: '#8b949e', marginBottom: 14, paddingLeft: 2 }}>
              {form.latitude}, {form.longitude}
            </div>
          )}
          {konumDurum === 'error' && (
            <div style={{ fontSize: 12, color: '#f87171', marginBottom: 14 }}>{konumHata}</div>
          )}

          {/* Şehir + İlçe */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
            <div>
              <label style={labelStyle}>Şehir</label>
              <input
                value={form.city}
                onChange={e => setForm({ ...form, city: e.target.value })}
                placeholder="İzmir"
                style={inputStyle}
              />
            </div>
            <div>
              <label style={labelStyle}>İlçe</label>
              <input
                value={form.district}
                onChange={e => setForm({ ...form, district: e.target.value })}
                placeholder="Bornova"
                style={inputStyle}
              />
            </div>
          </div>

          {/* Adres */}
          <label style={labelStyle}>Adres</label>
          <input
            value={form.address}
            onChange={e => setForm({ ...form, address: e.target.value })}
            placeholder="Atatürk Cad. No:12"
            style={inputStyle}
          />

          {/* Adres Tarifi */}
          <label style={labelStyle}>Adres Tarifi</label>
          <textarea
            value={form.address_note}
            onChange={e => setForm({ ...form, address_note: e.target.value })}
            placeholder="Örn: Kavşaktan sağa dön, sarı bina..."
            rows={2}
            style={{ ...inputStyle, resize: 'vertical' }}
          />

          {/* Telefon */}
          <label style={labelStyle}>Telefon</label>
          <input
            value={form.phone}
            onChange={e => setForm({ ...form, phone: e.target.value })}
            placeholder="0555 123 4567"
            type="tel"
            style={inputStyle}
          />

          {/* Açıklama */}
          <label style={labelStyle}>Açıklama</label>
          <textarea
            value={form.description}
            onChange={e => setForm({ ...form, description: e.target.value })}
            placeholder="Kısa bir açıklama..."
            rows={2}
            style={{ ...inputStyle, resize: 'vertical' }}
          />

          {/* Nöbetçi */}
          <label style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20, cursor: 'pointer' }}>
            <input
              type="checkbox"
              checked={form.is_emergency}
              onChange={e => setForm({ ...form, is_emergency: e.target.checked })}
              style={{ width: 18, height: 18, accentColor: '#ef4444' }}
            />
            <span style={{ fontSize: 13, color: '#8b949e' }}>🔴 Nöbetçi / 7/24 Acil Destek</span>
          </label>

          {hata && (
            <div style={{ color: '#f87171', fontSize: 13, marginBottom: 12 }}>{hata}</div>
          )}

          <button
            onClick={handleGonder}
            disabled={gonderiliyor}
            style={{
              width: '100%', padding: '14px 0', borderRadius: 10,
              background: '#22c55e', color: '#0d1117',
              border: 'none', fontWeight: 700, fontSize: 15,
              cursor: gonderiliyor ? 'not-allowed' : 'pointer',
              opacity: gonderiliyor ? 0.7 : 1,
            }}
          >
            {gonderiliyor ? 'Gönderiliyor...' : 'İncelemeye Gönder'}
          </button>
        </div>
      </div>
    </div>
  );
}

const labelStyle: React.CSSProperties = {
  display: 'block', fontSize: 12, color: '#8b949e', marginBottom: 6, fontWeight: 500,
};

const inputStyle: React.CSSProperties = {
  width: '100%', background: '#0d1117', border: '1px solid #30363d',
  borderRadius: 8, color: '#e6edf3', padding: '10px 12px',
  fontSize: 14, marginBottom: 14, boxSizing: 'border-box',
  fontFamily: "'IBM Plex Sans', sans-serif",
};
