'use client';

import dynamic from 'next/dynamic';
import { useSearchParams } from 'next/navigation';
import { useState, useEffect, useCallback, useRef } from 'react';
import PoiDetay from './PoiDetay';
import PoiEkleModal from './PoiEkleModal';
import { POI_HIYERARSI, POI_TUM_ALT_KATEGORILER, POI_ALT_ETIKETLER } from '../../lib/poi-constants';

const PoiHarita = dynamic(() => import('./PoiHarita'), {
  ssr: false,
  loading: () => (
    <div style={{
      flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
      background: '#0d1117', color: '#8b949e', fontSize: 14,
    }}>
      Harita yükleniyor...
    </div>
  ),
});

export interface PoiItem {
  id: string;
  name: string;
  category: string;
  latitude: number;
  longitude: number;
  tags: string[];
  badges: Record<string, boolean>;
  avg_rating: number;
  review_count: number;
  is_emergency: boolean;
  distance_m: number | null;
  ranking_score: number;
}

export interface BoundingBox {
  min_lng: number;
  min_lat: number;
  max_lng: number;
  max_lat: number;
}

// poi-constants.ts'den türetiliyor — burada değişiklik yapma
// PoiHarita pin ikonu için düzleştirilmiş tam liste (eski kategoriler dahil)
export const KATEGORILER = [
  { key: 'hepsi', label: 'Hepsi', icon: '🗺️', pinColor: '#8b949e' },
  ...POI_TUM_ALT_KATEGORILER.map(k => ({ key: k.value, label: k.label, icon: k.icon, pinColor: k.pinColor })),
];

const ALT_ETIKETLER: Record<string, string[]> = POI_ALT_ETIKETLER;

// Türkiye bounding box (ilk açılış için)
const TR_BBOX: BoundingBox = {
  min_lng: 25.0, min_lat: 35.0,
  max_lng: 45.0, max_lat: 42.5,
};

type Gorunum = 'liste' | 'harita' | 'yukler';

export interface YakinYukItem {
  id: string;
  listing_type: string;
  origin_city: string;
  origin_district: string | null;
  dest_city: string | null;
  dest_district: string | null;
  vehicle_type: string[] | null;
  body_type: string[] | null;
  price_offer: number | null;
  price_negotiable: boolean;
  available_date: string | null;
  date_flexible: boolean;
  created_at: string;
  eslesme: 'ilce' | 'il';
}

export default function YolRehberiClient() {
  // Landing page'deki hizmet kartlarından gelen deep-link: ?anaKategori=tamir_bakim&altKategori=lastikci
  const searchParams = useSearchParams();
  const [pois, setPois] = useState<PoiItem[]>([]);
  const [poiTotal, setPoiTotal] = useState<number | null>(null);
  const [yukleniyor, setYukleniyor] = useState(false);
  // Ana kategori seçimi ('hepsi' | ana kategori value) — geçersiz/eksik param varsa 'hepsi'e düşer
  const [aktifAnaKat, setAktifAnaKat] = useState(() => {
    const p = searchParams.get('anaKategori');
    return p && POI_HIYERARSI.some(a => a.value === p) ? p : 'hepsi';
  });
  // Seçili alt kategoriler (çoklu veya tekli — ana kategorinin cokluSecim'ine göre)
  const [aktifAltKatlar, setAktifAltKatlar] = useState<string[]>(() => {
    const anaP = searchParams.get('anaKategori');
    const altP = searchParams.get('altKategori');
    const ana = POI_HIYERARSI.find(a => a.value === anaP);
    return ana && altP && ana.altlar.some(alt => alt.value === altP) ? [altP] : [];
  });
  // Backward-compat: tek kategori filtresi için
  const aktifKategori = aktifAltKatlar.length === 1 ? aktifAltKatlar[0] : aktifAltKatlar.length === 0 ? aktifAnaKat : 'hepsi';
  const [aktifEtiketler, setAktifEtiketler] = useState<string[]>([]);
  const [secilenPoi, setSecilenPoi] = useState<string | null>(null);
  const [ekleModalAcik, setEkleModalAcik] = useState(false);
  const [gorunum, setGorunum] = useState<Gorunum>('liste');
  const [userLat, setUserLat] = useState<number | null>(null);
  const [userLng, setUserLng] = useState<number | null>(null);
  const [konumIzni, setKonumIzni] = useState<'bekleniyor' | 'tamam' | 'reddedildi'>('bekleniyor');
  const bboxRef = useRef<BoundingBox | null>(null);
  const fetchTimerRef = useRef<NodeJS.Timeout | null>(null);

  // Yakınımdaki Yükler (il bazlı)
  const [yakinYukler, setYakinYukler] = useState<YakinYukItem[]>([]);
  const [yakinIl, setYakinIl] = useState<string | null>(null);
  const [yakinYukleniyor, setYakinYukleniyor] = useState(false);
  const [yakinYuklendi, setYakinYuklendi] = useState(false);

  // Kullanıcı konumunu al
  useEffect(() => {
    if (!navigator.geolocation) {
      setKonumIzni('reddedildi');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      pos => {
        setUserLat(pos.coords.latitude);
        setUserLng(pos.coords.longitude);
        setKonumIzni('tamam');
      },
      () => setKonumIzni('reddedildi')
    );
  }, []);

  // Konum gelince veya filtre değişince POI'leri çek
  const fetchPois = useCallback(async (bbox: BoundingBox) => {
    if (fetchTimerRef.current) clearTimeout(fetchTimerRef.current);
    fetchTimerRef.current = setTimeout(async () => {
      setYukleniyor(true);
      try {
        // Kategori parametresi hesapla
        const anaKatAltlar = aktifAnaKat !== 'hepsi'
          ? (POI_HIYERARSI.find(a => a.value === aktifAnaKat)?.altlar.map(a => a.value) ?? [])
          : [];
        const gonderilecekKatlar = aktifAltKatlar.length > 0 ? aktifAltKatlar : anaKatAltlar;

        const params = new URLSearchParams({
          min_lng: bbox.min_lng.toString(),
          min_lat: bbox.min_lat.toString(),
          max_lng: bbox.max_lng.toString(),
          max_lat: bbox.max_lat.toString(),
          limit: gorunum === 'harita' ? '300' : '30',
        });
        if (gonderilecekKatlar.length > 0) params.set('categories', gonderilecekKatlar.join(','));
        if (aktifEtiketler.length) params.set('tags', aktifEtiketler.join(','));

        if (userLat) params.set('lat', userLat.toString());
        if (userLng) params.set('lng', userLng.toString());

        const res = await fetch(`/api/poi?${params.toString()}`);
        const json = await res.json();
        if (json.success) { setPois(json.data); setPoiTotal(json.total ?? json.data.length); }
      } catch (err) {
        console.error('POI fetch hatası:', err);
      } finally {
        setYukleniyor(false);
      }
    }, 300);
  }, [aktifAnaKat, aktifAltKatlar, aktifEtiketler, userLat, userLng]);

  // Liste modunda her zaman TR_BBOX kullan — sıralama algoritması
  // zaten mesafe+puana göre en iyi 30'u öne getirir.
  // Harita modunda bbox haritanın görünüm alanından gelir (handleBoundsChange).
  useEffect(() => {
    const bbox = gorunum === 'harita' && userLat && userLng
      ? {
          min_lng: userLng - 0.5, min_lat: userLat - 0.3,
          max_lng: userLng + 0.5, max_lat: userLat + 0.3,
        }
      : TR_BBOX;
    bboxRef.current = bbox;
    fetchPois(bbox);
  }, [fetchPois, userLat, userLng, gorunum]);

  const handleBoundsChange = useCallback((bbox: BoundingBox) => {
    bboxRef.current = bbox;
    fetchPois(bbox);
  }, [fetchPois]);

  // Yakınımdaki Yükler sekmesi açıldığında (ve konum hazır olduğunda) bir kere çek
  useEffect(() => {
    if (gorunum !== 'yukler' || !userLat || !userLng || yakinYuklendi) return;
    setYakinYukleniyor(true);
    fetch(`/api/listings/yakin?lat=${userLat}&lng=${userLng}`)
      .then(res => res.json())
      .then(json => {
        if (json.success) {
          setYakinYukler(json.data);
          setYakinIl(json.il);
        }
        setYakinYuklendi(true);
      })
      .catch(err => console.error('Yakın yük fetch hatası:', err))
      .finally(() => setYakinYukleniyor(false));
  }, [gorunum, userLat, userLng, yakinYuklendi]);

  const handleAnaKat = (anaKey: string) => {
    setAktifAnaKat(anaKey);
    setAktifAltKatlar([]);
    setAktifEtiketler([]);
  };

  const toggleAltKat = (altKey: string) => {
    const anaKat = POI_HIYERARSI.find(a => a.value === aktifAnaKat);
    if (!anaKat) return;
    if (anaKat.cokluSecim) {
      setAktifAltKatlar(prev =>
        prev.includes(altKey) ? prev.filter(k => k !== altKey) : [...prev, altKey]
      );
    } else {
      // Tekli seçim (Operasyon Noktaları)
      setAktifAltKatlar(prev => prev.includes(altKey) ? [] : [altKey]);
    }
    setAktifEtiketler([]);
  };

  const toggleEtiket = (etiket: string) => {
    setAktifEtiketler(prev =>
      prev.includes(etiket) ? prev.filter(e => e !== etiket) : [...prev, etiket]
    );
  };

  const aktifAnaKatConfig = POI_HIYERARSI.find(a => a.value === aktifAnaKat);
  // Tek alt kategori seçiliyse onun tag önerilerini göster
  const altEtiketler = aktifAltKatlar.length === 1 ? (ALT_ETIKETLER[aktifAltKatlar[0]] || []) : [];

  return (
    <div style={{
      display: 'flex', flexDirection: 'column', height: '100dvh',
      background: '#0d1117', color: '#e6edf3',
      fontFamily: "'IBM Plex Sans', sans-serif", overflow: 'hidden',
    }}>

      {/* ── Header ── */}
      <header style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '12px 16px', background: '#161b22',
        borderBottom: '1px solid #21262d', flexShrink: 0,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <a href="/" style={{ color: '#22c55e', fontWeight: 700, fontSize: 17, textDecoration: 'none' }}>
            Yükegel
          </a>
          <span style={{ color: '#30363d' }}>|</span>
          <span style={{ color: '#e6edf3', fontWeight: 600, fontSize: 15 }}>Yol Rehberi</span>
        </div>

        <div style={{ display: 'flex', gap: 8 }}>
          {/* Görünüm toggle */}
          <div style={{
            display: 'flex', background: '#21262d',
            borderRadius: 8, overflow: 'hidden', border: '1px solid #30363d',
          }}>
            <button
              onClick={() => setGorunum('liste')}
              style={{
                padding: '7px 12px', border: 'none', fontSize: 13,
                background: gorunum === 'liste' ? '#22c55e' : 'transparent',
                color: gorunum === 'liste' ? '#0d1117' : '#8b949e',
                fontWeight: gorunum === 'liste' ? 700 : 400,
                cursor: 'pointer',
              }}
            >
              ☰ Liste
            </button>
            <button
              onClick={() => setGorunum('harita')}
              style={{
                padding: '7px 12px', border: 'none', fontSize: 13,
                background: gorunum === 'harita' ? '#22c55e' : 'transparent',
                color: gorunum === 'harita' ? '#0d1117' : '#8b949e',
                fontWeight: gorunum === 'harita' ? 700 : 400,
                cursor: 'pointer',
              }}
            >
              🗺️ Harita
            </button>
            <button
              onClick={() => setGorunum('yukler')}
              style={{
                padding: '7px 12px', border: 'none', fontSize: 13,
                background: gorunum === 'yukler' ? '#22c55e' : 'transparent',
                color: gorunum === 'yukler' ? '#0d1117' : '#8b949e',
                fontWeight: gorunum === 'yukler' ? 700 : 400,
                cursor: 'pointer',
              }}
            >
              📦 Yükler
            </button>
          </div>

          {/* Yeni yer ekle */}
          <button
            onClick={() => setEkleModalAcik(true)}
            style={{
              padding: '7px 12px', borderRadius: 8, border: 'none',
              background: '#21262d', color: '#e6edf3',
              fontSize: 18, cursor: 'pointer', lineHeight: 1,
            }}
            title="Yeni Yer Ekle"
          >
            +
          </button>
        </div>
      </header>

      {/* ── Ana Kategori Chips ── */}
      <div style={{
        display: 'flex', gap: 8, padding: '10px 14px',
        overflowX: 'auto', flexShrink: 0,
        background: '#161b22', borderBottom: '1px solid #21262d',
        scrollbarWidth: 'none',
      }}>
        {/* Hepsi */}
        <button
          onClick={() => handleAnaKat('hepsi')}
          style={{
            display: 'flex', alignItems: 'center', gap: 5,
            padding: '6px 12px', borderRadius: 20, border: 'none',
            background: aktifAnaKat === 'hepsi' ? '#8b949e' : '#21262d',
            color: aktifAnaKat === 'hepsi' ? '#fff' : '#8b949e',
            fontWeight: aktifAnaKat === 'hepsi' ? 600 : 400,
            fontSize: 13, cursor: 'pointer', whiteSpace: 'nowrap',
            flexShrink: 0, transition: 'all 0.12s',
          }}
        >
          <span>🗺️</span><span>Hepsi</span>
        </button>

        {/* Ana kategoriler */}
        {POI_HIYERARSI.map(ana => (
          <button
            key={ana.value}
            onClick={() => handleAnaKat(ana.value)}
            style={{
              display: 'flex', alignItems: 'center', gap: 5,
              padding: '6px 12px', borderRadius: 20, border: 'none',
              background: aktifAnaKat === ana.value ? ana.pinColor : '#21262d',
              color: aktifAnaKat === ana.value ? '#fff' : '#8b949e',
              fontWeight: aktifAnaKat === ana.value ? 600 : 400,
              fontSize: 13, cursor: 'pointer', whiteSpace: 'nowrap',
              flexShrink: 0, transition: 'all 0.12s',
            }}
          >
            <span>{ana.icon}</span><span>{ana.label}</span>
          </button>
        ))}
      </div>

      {/* ── Alt Kategori Chips (ana kategori seçiliyse) ── */}
      {aktifAnaKatConfig && (
        <div style={{
          display: 'flex', gap: 6, padding: '8px 14px',
          overflowX: 'auto', flexShrink: 0,
          background: '#0d1117', borderBottom: '1px solid #21262d',
          scrollbarWidth: 'none', alignItems: 'center',
        }}>
          {aktifAnaKatConfig.altlar.map(alt => {
            const secili = aktifAltKatlar.includes(alt.value);
            return (
              <button
                key={alt.value}
                onClick={() => toggleAltKat(alt.value)}
                style={{
                  display: 'flex', alignItems: 'center', gap: 4,
                  padding: '5px 11px', borderRadius: 16,
                  border: `1px solid ${secili ? alt.pinColor : '#30363d'}`,
                  background: secili ? alt.pinColor + '22' : 'transparent',
                  color: secili ? alt.pinColor : '#8b949e',
                  fontSize: 12, cursor: 'pointer', whiteSpace: 'nowrap',
                  flexShrink: 0, fontWeight: secili ? 600 : 400,
                }}
              >
                <span>{alt.icon}</span><span>{alt.label}</span>
              </button>
            );
          })}
          {aktifAltKatlar.length > 0 && (
            <button
              onClick={() => setAktifAltKatlar([])}
              style={{
                padding: '4px 9px', borderRadius: 12, border: '1px solid #30363d',
                background: 'transparent', color: '#4b5563', fontSize: 11, cursor: 'pointer',
                flexShrink: 0, whiteSpace: 'nowrap',
              }}
            >
              ✕ Temizle
            </button>
          )}
        </div>
      )}

      {/* ── Özellik Etiketleri (tek alt kategori seçiliyse) ── */}
      {altEtiketler.length > 0 && (
        <div style={{
          display: 'flex', gap: 6, padding: '6px 14px',
          overflowX: 'auto', flexShrink: 0,
          background: '#0d1117', borderBottom: '1px solid #21262d',
          scrollbarWidth: 'none',
        }}>
          {altEtiketler.map(etiket => (
            <button
              key={etiket}
              onClick={() => toggleEtiket(etiket)}
              style={{
                padding: '4px 10px', borderRadius: 16,
                border: `1px solid ${aktifEtiketler.includes(etiket) ? '#22c55e' : '#30363d'}`,
                background: aktifEtiketler.includes(etiket) ? '#14532d' : 'transparent',
                color: aktifEtiketler.includes(etiket) ? '#22c55e' : '#8b949e',
                fontSize: 11, cursor: 'pointer', whiteSpace: 'nowrap',
                flexShrink: 0,
              }}
            >
              {etiket}
            </button>
          ))}
        </div>
      )}

      {/* ── İçerik Alanı ── */}
      <div style={{ flex: 1, overflow: 'hidden', position: 'relative', display: 'flex', flexDirection: 'column' }}>

        {/* LİSTE GÖRÜNÜMÜ */}
        {gorunum === 'liste' && (
          <div style={{ flex: 1, overflowY: 'auto', padding: '12px 14px 24px' }}>

            {/* Konum durumu */}
            {konumIzni === 'bekleniyor' && (
              <div style={{ fontSize: 13, color: '#8b949e', textAlign: 'center', padding: '12px 0 4px' }}>
                📍 Konum alınıyor...
              </div>
            )}
            {konumIzni === 'reddedildi' && (
              <div style={{
                fontSize: 12, color: '#8b949e', background: '#161b22',
                borderRadius: 8, padding: '8px 12px', marginBottom: 12,
                border: '1px solid #21262d',
              }}>
                ⚠️ Konum izni verilmedi — mesafe hesaplanamıyor. Tüm Türkiye gösteriliyor.
              </div>
            )}

            {/* Başlık + sayaç */}
            <div style={{
              display: 'flex', alignItems: 'center', justifyContent: 'space-between',
              marginBottom: 12,
            }}>
              <span style={{ fontSize: 13, fontWeight: 600, color: '#8b949e' }}>
                Yakınındaki En İyi Noktalar
              </span>
              {yukleniyor
                ? <span style={{ fontSize: 12, color: '#8b949e' }}>Güncelleniyor...</span>
                : <span style={{ fontSize: 12, color: '#30363d' }}>{poiTotal ?? pois.length} sonuç</span>
              }
            </div>

            {/* Boş durum */}
            {!yukleniyor && pois.length === 0 && (
              <div style={{
                textAlign: 'center', padding: '48px 20px',
                color: '#8b949e', fontSize: 14,
              }}>
                <div style={{ fontSize: 36, marginBottom: 12 }}>📍</div>
                <div>Bu bölgede kayıtlı konum bulunamadı.</div>
                <button
                  onClick={() => setEkleModalAcik(true)}
                  style={{
                    marginTop: 16, padding: '9px 18px', borderRadius: 8,
                    background: '#22c55e', color: '#0d1117',
                    border: 'none', fontWeight: 600, fontSize: 13, cursor: 'pointer',
                  }}
                >
                  + İlk yeri sen ekle
                </button>
              </div>
            )}

            {/* POI listesi — yakından uzağa */}
            {[...pois]
              .sort((a, b) => {
                if (a.distance_m == null && b.distance_m == null) return 0;
                if (a.distance_m == null) return 1;
                if (b.distance_m == null) return -1;
                return a.distance_m - b.distance_m;
              })
              .map((poi, index) => (
                <PoiListeKart
                  key={poi.id}
                  poi={poi}
                  rank={index + 1}
                  onClick={() => setSecilenPoi(poi.id)}
                />
              ))}
          </div>
        )}

        {/* HARİTA GÖRÜNÜMÜ */}
        {gorunum === 'harita' && (
          <div style={{ flex: 1, position: 'relative' }}>
            <PoiHarita
              pois={pois}
              userLat={userLat}
              userLng={userLng}
              onBoundsChange={handleBoundsChange}
              onPoiClick={id => setSecilenPoi(id)}
              aktifKategori={aktifKategori}
            />
            {yukleniyor && (
              <div style={{
                position: 'absolute', top: 12, left: '50%', transform: 'translateX(-50%)',
                background: '#161b22', color: '#8b949e',
                padding: '5px 14px', borderRadius: 20,
                fontSize: 12, border: '1px solid #30363d', zIndex: 900,
              }}>
                Güncelleniyor...
              </div>
            )}
          </div>
        )}
        {/* YÜKLER GÖRÜNÜMÜ */}
        {gorunum === 'yukler' && (
          <div style={{ flex: 1, overflowY: 'auto', padding: '12px 14px 24px' }}>
            {konumIzni === 'bekleniyor' && (
              <div style={{ fontSize: 13, color: '#8b949e', textAlign: 'center', padding: '12px 0 4px' }}>
                📍 Konum alınıyor...
              </div>
            )}
            {konumIzni === 'reddedildi' && (
              <div style={{
                fontSize: 12, color: '#8b949e', background: '#161b22',
                borderRadius: 8, padding: '8px 12px', marginBottom: 12,
                border: '1px solid #21262d',
              }}>
                ⚠️ Konum izni verilmeden yükler gösterilemiyor. Tarayıcı ayarlarından konuma izin ver.
              </div>
            )}

            {konumIzni === 'tamam' && (
              <>
                <div style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                  marginBottom: 12,
                }}>
                  <span style={{ fontSize: 13, fontWeight: 600, color: '#8b949e' }}>
                    {yakinIl ? `${yakinIl} çevresindeki yükler` : 'Yakınımdaki Yükler'}
                  </span>
                  {yakinYukleniyor
                    ? <span style={{ fontSize: 12, color: '#8b949e' }}>Yükleniyor...</span>
                    : <span style={{ fontSize: 12, color: '#30363d' }}>{yakinYukler.length} sonuç</span>
                  }
                </div>

                {!yakinYukleniyor && yakinYukler.length === 0 && yakinYuklendi && (
                  <div style={{
                    textAlign: 'center', padding: '48px 20px',
                    color: '#8b949e', fontSize: 14,
                  }}>
                    <div style={{ fontSize: 36, marginBottom: 12 }}>📦</div>
                    <div>{yakinIl ? `${yakinIl} bölgesinde aktif yük ilanı bulunamadı.` : 'Bu bölgede aktif yük ilanı bulunamadı.'}</div>
                  </div>
                )}

                {yakinYukler.map(yuk => (
                  <YukListeKart key={yuk.id} yuk={yuk} />
                ))}
              </>
            )}
          </div>
        )}
      </div>

      {/* ── POI Detay ── */}
      {secilenPoi && (
        <PoiDetay
          poiId={secilenPoi}
          userLat={userLat}
          userLng={userLng}
          onKapat={() => setSecilenPoi(null)}
        />
      )}

      {/* ── Yeni POI Ekle ── */}
      {ekleModalAcik && (
        <PoiEkleModal
          userLat={userLat}
          userLng={userLng}
          onKapat={() => setEkleModalAcik(false)}
          onBasarili={() => {
            setEkleModalAcik(false);
            if (bboxRef.current) fetchPois(bboxRef.current);
          }}
        />
      )}
    </div>
  );
}

// ── POI Liste Kartı ───────────────────────────────────────────
function PoiListeKart({ poi, rank, onClick }: { poi: PoiItem; rank: number; onClick: () => void }) {
  const kat = KATEGORILER.find(k => k.key === poi.category) ?? { icon: '📍', pinColor: '#8b949e', label: poi.category };

  const mesafeStr = poi.distance_m == null
    ? null
    : poi.distance_m < 1000
      ? `${Math.round(poi.distance_m)} m`
      : `${(poi.distance_m / 1000).toFixed(1)} km`;

  return (
    <button
      onClick={onClick}
      style={{
        display: 'flex', alignItems: 'center', gap: 12,
        width: '100%', background: '#161b22',
        border: '1px solid #21262d', borderRadius: 12,
        padding: '12px 14px', marginBottom: 10,
        cursor: 'pointer', textAlign: 'left',
      }}
    >
      {/* Kategori + sıralama */}
      <div style={{ position: 'relative', flexShrink: 0 }}>
        <div style={{
          width: 44, height: 44, borderRadius: 10,
          background: kat.pinColor,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: 20,
        }}>
          {kat.icon}
        </div>
        {rank <= 3 && (
          <div style={{
            position: 'absolute', top: -6, right: -6,
            width: 18, height: 18, borderRadius: '50%',
            background: rank === 1 ? '#eab308' : rank === 2 ? '#9ca3af' : '#d97706',
            color: '#0d1117', fontSize: 10, fontWeight: 700,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>
            {rank}
          </div>
        )}
      </div>

      {/* Bilgiler */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontWeight: 600, fontSize: 15, color: '#e6edf3',
          marginBottom: 3, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
        }}>
          {poi.name}
          {poi.is_emergency && (
            <span style={{ marginLeft: 6, fontSize: 11, color: '#ef4444' }}>🔴</span>
          )}
        </div>

        {/* Mesafe + puan — en önemli bilgiler büyük */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 4 }}>
          {mesafeStr && (
            <span style={{
              fontSize: 15, fontWeight: 700,
              color: poi.distance_m! < 2000 ? '#22c55e' : '#e6edf3',
            }}>
              {mesafeStr}
            </span>
          )}
          {poi.avg_rating > 0 && (
            <span style={{ fontSize: 13, color: '#eab308', display: 'flex', alignItems: 'center', gap: 3 }}>
              ★ <strong>{poi.avg_rating.toFixed(1)}</strong>
              <span style={{ color: '#8b949e', fontWeight: 400 }}>({poi.review_count})</span>
            </span>
          )}
        </div>

        {/* Etiketler */}
        {poi.tags.length > 0 && (
          <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap' }}>
            {poi.tags.slice(0, 3).map(tag => (
              <span key={tag} style={{
                fontSize: 11, color: '#22c55e',
                background: '#14532d', padding: '2px 6px', borderRadius: 4,
              }}>
                {tag}
              </span>
            ))}
          </div>
        )}
      </div>

      <span style={{ color: '#30363d', fontSize: 18, flexShrink: 0 }}>›</span>
    </button>
  );
}

// ── Yakın Yük Liste Kartı ──────────────────────────────────────────────────────
function YukListeKart({ yuk }: { yuk: YakinYukItem }) {
  const fiyatStr = yuk.price_offer
    ? `${yuk.price_offer.toLocaleString('tr-TR')} TL${yuk.price_negotiable ? ' (pazarlık)' : ''}`
    : 'Fiyat belirtilmemiş';

  const zamanStr = (() => {
    const fark = Date.now() - new Date(yuk.created_at).getTime();
    const saat = Math.floor(fark / 3_600_000);
    if (saat < 1) return 'az önce';
    if (saat < 24) return `${saat} saat önce`;
    return `${Math.floor(saat / 24)} gün önce`;
  })();

  return (
    <a
      href={`/ilan/${yuk.id}`}
      style={{
        display: 'block', width: '100%', background: '#161b22',
        border: '1px solid #21262d', borderRadius: 12,
        padding: '12px 14px', marginBottom: 10,
        textDecoration: 'none', color: 'inherit',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
        <span style={{ fontSize: 15, fontWeight: 700, color: '#e6edf3' }}>
          {yuk.origin_district ? `${yuk.origin_city}, ${yuk.origin_district}` : yuk.origin_city}
        </span>
        <span style={{ color: '#30363d' }}>→</span>
        <span style={{ fontSize: 15, fontWeight: 700, color: '#e6edf3' }}>
          {yuk.dest_city ? (yuk.dest_district ? `${yuk.dest_city}, ${yuk.dest_district}` : yuk.dest_city) : '—'}
        </span>
        {yuk.eslesme === 'ilce' && (
          <span style={{
            fontSize: 10, color: '#22c55e', background: '#14532d',
            padding: '2px 6px', borderRadius: 4, fontWeight: 600,
          }}>
            YAKININDA
          </span>
        )}
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 4, flexWrap: 'wrap' }}>
        <span style={{ fontSize: 13, fontWeight: 600, color: '#22c55e' }}>{fiyatStr}</span>
        {yuk.vehicle_type && yuk.vehicle_type.length > 0 && (
          <span style={{ fontSize: 12, color: '#8b949e' }}>{yuk.vehicle_type.join(', ')}</span>
        )}
      </div>

      <div style={{ fontSize: 11, color: '#4b5563' }}>{zamanStr}</div>
    </a>
  );
}
